// src/lib/k3FormGorselleri.ts
//
// K3 (Gönderen – Paketleyen – Yükleyen – Dolduran Kontrol Dökümanı)
// formunun ORİJİNAL docx'ten LibreOffice ile birebir (tasarım, görseller,
// tablo hücre birleşimleri korunarak) PDF'e çevrilip 150 DPI PNG olarak
// dışa aktarılmış hâli — her sayfa TasimaEvraki.tsx ve BelgeOlusturForm.tsx
// içinde arka plan görseli olarak kullanılır, otomatik doldurulacak
// veriler bu görselin ÜZERİNE (ölçülmüş koordinatlarda) yazılır.
//
// NOT (güncelleme): "3. Gönderen-Paketleyen", "Yükleyen" ve "Dolduran
// Kontrolleri" tablolarındaki "Onay" (√/X/i) sütunu orijinal docx'te
// sayfalar arasında TUTARSIZ genişlikteydi (50mm / 57.5mm) ve gereğinden
// geniş tutulmuştu. python-docx ile tblGrid seviyesinde düzenlenip
// üçü de 25mm'ye (kullanıcının istediği ~%50 azaltma) sabitlendi, farkı
// "Kontrol Edilecek Hususlar" sütununa eklendi — şimdi üç tablo da aynı
// hizada. Bu değişiklik nedeniyle TasimaEvraki.tsx'teki "Dolduran
// Kontrolleri" checkbox koordinatları da yeniden ölçülüp güncellendi.
//
// NOT (madde 11): K3_FORM_SAYFA1'deki 11. madde metni "Tank veya Sınıf 1
// (patlayıcı) taşımalarında araç için geçerli ADR Uygunluk Belgesi / Taşıt
// Uygunluk Belgesi mevcut mu? (ADR Bölüm 9 – Yönetmelik Md.6, Md.18/1-c)"
// olarak düzeltildi ("dökme yük" ifadesi çıkarıldı). Yalnızca o hücre
// yeniden çizildi, görselin geri kalanı birebir aynı.
//
// Bu dosya DİNAMİK import edilir (await import(...)) — ana sayfa yükünü
// artırmasın diye, yalnızca PDF üretilirken yüklenir.
//
// NOT: base64 verisi bilinçli olarak TEK SATIR (chunk'lanmamış) tutulur
// — çok sayıda "+" ile birleştirilmiş küçük parçalar, build sürecinde
// bir regex/AST işleminin aşırı yavaşlayıp bellek taşırmasına
// (RangeError: Maximum call stack size exceeded, OOM) yol açabiliyor.
//
// 2026-10-21: 1. sayfanın üstündeki "GÖNDEREN KONTROL DÖKÜMANI" başlığı görselden kırpıldı; bu yazı artık
// Belge Oluştur'un standart başlık kutusunun orta hücresinde ALT SATIR olarak basılıyor (BelgeOlusturForm.tsx).

export const K3_FORM_SAYFA1 =
  "data:image/png;base64,";

